// Normalize inputs from the blog-post-outline webhook.
const input = $input.first().json;
const form = (input && typeof input.body === 'object' && input.body !== null && Object.keys(input.body).length > 0)
  ? input.body
  : input;

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (...keys) => {
  for (const k of keys) {
    if (form[k] !== undefined && form[k] !== null && form[k] !== '') return form[k];
  }
  const targets = keys.map(norm);
  for (const k of Object.keys(form)) {
    const n = norm(k);
    if (targets.some(t => n === t || n.startsWith(t))) return form[k];
  }
  return '';
};

const toArr = v => {
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  if (typeof v === 'string') return v.split(/[,;\n]/).map(s => s.trim()).filter(Boolean);
  return [];
};

const parseBool = v => {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') return v.toLowerCase() === 'true' || v === '1';
  if (typeof v === 'number') return v !== 0;
  return false;
};

return [{
  json: {
    topic: pick('topic', 'Topic') || '',
    voice: pick('voice', 'Voice') || '',
    anecdotes: pick('anecdotes', 'Anecdotes') || '',
    opinions: pick('opinions', 'Opinions') || '',
    stats_enabled: parseBool(pick('stats_enabled', 'Stats Enabled', 'statsEnabled')),
    focus_keyword: pick('focus_keyword', 'Focus Keyword', 'focusKeyword') || '',
    header_keywords: toArr(pick('header_keywords', 'Header Keywords', 'headerKeywords')),
    entities: toArr(pick('entities', 'Entities')),
    common_keywords: toArr(pick('common_keywords', 'Common Keywords', 'commonKeywords')),
    extra_keywords: toArr(pick('extra_keywords', 'Extra Keywords', 'extraKeywords')),
    target_word_count: parseInt(pick('target_word_count', 'Target Word Count', 'targetWordCount')) || 0,
    intent_context_text: String(pick('intent_context_text', 'intentContextText') || '').trim(),
    salience_context_text: String(pick('salience_context_text', 'salienceContextText') || '').trim(),
    audience_context_text: String(pick('audience_context_text', 'audienceContextText') || '').trim(),
    internal_links: Array.isArray(form.internal_links) ? form.internal_links.filter(u => typeof u === 'string' && /^https?:\/\//.test(u)) : []
  }
}];

// If stats_enabled, search Exa for statistics/data related to the topic
// and summarise with Gemini Flash.
//
// REPLACE these constants with your real keys:
//   OPENROUTER_API_KEY
//   EXA_API_KEY

const OPENROUTER_API_KEY = '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';
const EXA_API_KEY = 'b0beb520-610f-4246-ade5-7620631a89aa';
const STATS_MODEL = 'google/gemini-2.5-flash';

const form = $('Normalize Outline Inputs').first().json;

if (!form.stats_enabled) {
  return [{
    json: {
      stats_enabled: false,
      stats_block: '',
      source_count: 0
    }
  }];
}

const query = (form.topic || form.focus_keyword || '').trim();
if (!query) {
  return [{ json: { stats_enabled: true, stats_block: '', source_count: 0, error: 'No topic or focus keyword' } }];
}

let statsBlock = '';
let sourceCount = 0;
let errorMsg = null;

try {
  // 1. Exa search
  const exaResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.exa.ai/search',
    headers: {
      'x-api-key': EXA_API_KEY,
      'Content-Type': 'application/json'
    },
    body: {
      query: query + ' statistics data study research',
      numResults: 8,
      type: 'neural',
      useAutoprompt: true
    },
    json: true,
    timeout: 30000
  });

  if (!exaResp || !Array.isArray(exaResp.results) || exaResp.results.length === 0) {
    errorMsg = 'No statistical sources found';
  } else {
    // 2. Fetch contents
    const ids = exaResp.results.slice(0, 8).map(r => r.id).filter(Boolean);
    const contentsResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.exa.ai/contents',
      headers: {
        'x-api-key': EXA_API_KEY,
        'Content-Type': 'application/json'
      },
      body: {
        ids,
        text: { maxCharacters: 4000, includeHtmlTags: false }
      },
      json: true,
      timeout: 30000
    });

    const textById = new Map();
    if (contentsResp && Array.isArray(contentsResp.results)) {
      for (const c of contentsResp.results) {
        if (c.id && c.text) textById.set(c.id, c.text);
      }
    }

    // Collect meaningful texts
    const texts = [];
    for (const r of exaResp.results) {
      const body = (textById.get(r.id) || '').trim();
      if (body.length > 100) {
        texts.push('[Source: ' + (r.title || r.url || 'unknown') + ']\n' + body);
        sourceCount++;
      }
      if (sourceCount >= 5) break;
    }

    if (texts.length === 0) {
      errorMsg = 'Exa results had insufficient text content';
    } else {
      // 3. Summarise with Gemini Flash
      const combined = texts.join('\n\n---\n\n');
      const llmResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://openrouter.ai/api/v1/chat/completions',
        headers: {
          'Authorization': 'Bearer ' + OPENROUTER_API_KEY,
          'Content-Type': 'application/json',
          'HTTP-Referer': 'https://shettymarketing.com',
          'X-Title': 'Blog Post Creator (n8n)'
        },
        body: {
          model: STATS_MODEL,
          messages: [
            { role: 'system', content: 'You are a research assistant. Extract relevant statistics, data points, percentages, study findings, and research results from the provided sources. Output a concise bullet-point list. Include the specific numbers and cite the source name in brackets. Format: "- [statistic] [source name]". If a source has no concrete data, skip it. Output only the bullet list, no preamble.' },
            { role: 'user', content: 'Extract all statistics, data points, and research findings from the following sources about "' + query + '". Return only the bullet-point list:\n\n' + combined }
          ],
          temperature: 0
        },
        json: true,
        timeout: 60000
      });

      statsBlock = llmResp?.choices?.[0]?.message?.content || '';
    }
  }
} catch (err) {
  errorMsg = 'Stats scraping failed: ' + (err.message || String(err));
}

return [{
  json: {
    stats_enabled: true,
    stats_block: statsBlock,
    source_count: sourceCount,
    error: errorMsg
  }
}];

// Build the OpenRouter request body for blog-post outline generation.
//
// REPLACE the OPENROUTER_API_KEY constant and tune OUTLINE_MODEL below.

const OPENROUTER_API_KEY = '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';
const OUTLINE_MODEL      = 'google/gemini-2.5-flash';

const form = $('Fetch Writing Style (Outline)').first().json;
const stats = $('Stats Scrape').first().json;

// Word count breakdown calculation
const targetWC = form.target_word_count || 0;
let wcBreakdown = '';

if (targetWC > 0) {
  const introWords = Math.round(targetWC * 0.10);
  const conclusionWords = Math.round(targetWC * 0.10);
  const bodyWords = targetWC - introWords - conclusionWords;
  const estimatedH2 = 5;
  const wordsPerH2 = Math.round(bodyWords / estimatedH2);

  wcBreakdown = '\n\nWORD COUNT TARGET: ' + targetWC + ' words (\u00b15% tolerance: ' + Math.round(targetWC * 0.95) + '-' + Math.round(targetWC * 1.05) + ' words)\n- Intro paragraph: ~' + introWords + ' words (above-the-fold, before first H2)\n- Each H2 section: ~' + wordsPerH2 + ' words (' + estimatedH2 + ' sections)\n- Conclusion: ~' + conclusionWords + ' words\n\nThe outline MUST have enough H2/H3 depth to support this word count. Each section description should include its target word count.';
}

const systemPrompt = 'You are a senior blog editor and SEO strategist. You write blog-post outlines that rank in Google AND are quoted by LLM-based search (ChatGPT, Gemini, Perplexity).\n\n' +
'GROUNDING RULES (ordered by priority):\n' +
'1. SEARCH INTENT INSIGHTS (HIGHEST PRIORITY): If <intent_context> contains content, treat it as authoritative truth about what users searching this topic actually want. Shape the outline to address the stated primary intent. Use sub-intents to inspire section topics. If a recommended page archetype is specified (listicle, guide, how-to, comparison, etc.), you MUST follow it exactly. Do NOT default to a generic guide structure if the intent calls for a listicle. If a modifier-SERP conflict is flagged, follow that guidance.\n' +
'2. SALIENCE INSIGHTS (SECOND HIGHEST PRIORITY): If <salience_context> contains content (must-cover entities, H2 candidates, supporting topics), weave must-cover entities using exact entity names. Use H2/H3 candidates from salience as structural anchors. Give must-cover entities their own H2/H3 if they are significant enough.\n' +
'3. Design the blog structure yourself. Choose the best H1 title, section headings, and flow based on the topic, voice, anecdotes, opinions, stats, and keyword context provided. Do NOT follow a fixed template -- let the content dictate the structure.\n' +
'4. The H1 must include the Focus Keyword naturally. It should read like a compelling blog title, not a keyword-stuffed headline.\n' +
'5. Every section body must be one or two short lines describing what the writer should cover in that section, citing which keywords / entities / anecdotes / stats to weave in. Do NOT write the actual paragraph content here -- outlines only.\n' +
'6. Weave keywords naturally: Focus Keyword in the H1 and intro, Header Keywords in H2/H3 headings, Entities where they add authority, Common/Extra Keywords throughout body descriptions.\n' +
'7. If <voice_context> is provided, write all section descriptions in that exact voice -- mirror the tone, style, perspective, and audience level described.\n' +
'8. If <anecdotes> are provided, place each anecdote in the most relevant section -- tag it as [Include anecdote: <summary>] in the section body.\n' +
'9. If <opinions> are provided, ensure at least 1-2 sections explicitly call out the unique/contrarian takes. Tag them as [POV: <summary>].\n' +
'10. If <stats_context> is provided (statistics and data points from live research), weave the most relevant stats into appropriate sections. Tag them as [Include stat: <summary>]. Do not fabricate new stats.\n' +
'11. AUDIENCE RESEARCH: If <audience_context> contains content (problem clusters with questions and content angles), use the user problems as primary inspiration for section topics. Address the top emotional/practical concerns early, not buried deep.' +
'14. INTERNAL LINKING: If <internal_links> is provided, identify 3-5 places where internal links are contextually relevant. Insert them as markdown links: [descriptive anchor text](URL). Anchor text must be natural and match the linked page topic. Only use a link when the surrounding content genuinely relates to that URL. Never force irrelevant links.' +
wcBreakdown + '\n\n' +
'TONE: Match the provided voice exactly. If no voice is provided, default to conversational, authoritative, and benefit-driven.\n\n' +
'OUTPUT: Plain markdown. No preamble. No trailing commentary. No code fences.';

const parts = [];
// PRIORITY ORDER: intent > salience > keywords > anecdotes/opinions > rest
parts.push('<intent_context>\n' + (form.intent_context_text || '(not provided)') + '\n</intent_context>');
parts.push('<salience_context>\n' + (form.salience_context_text || '(not provided)') + '\n</salience_context>');
parts.push('<marketer_inputs>\nFocus Keyword: ' + (form.focus_keyword || '(not set)') + '\nHeader Keywords: ' + ((form.header_keywords || []).join(', ') || '(not set)') + '\nEntities: ' + ((form.entities || []).join(', ') || '(not set)') + '\nCommon Keywords: ' + ((form.common_keywords || []).join(', ') || '(not set)') + '\nExtra Keywords: ' + ((form.extra_keywords || []).join(', ') || '(not set)') + (targetWC > 0 ? '\nTarget Word Count: ' + targetWC + ' words' : '') + '\n</marketer_inputs>');
if (form.anecdotes) parts.push('<anecdotes>\n' + form.anecdotes + '\n</anecdotes>');
if (form.opinions) parts.push('<opinions>\n' + form.opinions + '\n</opinions>');
parts.push('<topic>\n' + (form.topic || form.focus_keyword || '(not set)') + '\n</topic>');
if (form.voice) parts.push('<voice_context>\n' + form.voice + '\n</voice_context>');
if (stats.stats_block) parts.push('<stats_context>\n' + stats.stats_block + '\n</stats_context>');
parts.push('<audience_context>\n' + (form.audience_context_text || '(not provided)') + '\n</audience_context>');
if (form.internal_links && form.internal_links.length > 0) {
  parts.push('<internal_links>\nAvailable internal URLs for contextual linking. Only use when the surrounding content genuinely matches the URL topic. Use the URL path to judge relevance.\n' + form.internal_links.map(u => '- ' + u).join('\n') + '\n</internal_links>');
}
if (form.internal_links && form.internal_links.length > 0) {
  parts.push('<internal_links>\nAvailable internal URLs for contextual linking. Only use when the surrounding content genuinely matches the URL topic. Use the URL path to judge relevance.\n' + form.internal_links.map(u => '- ' + u).join('\n') + '\n</internal_links>');
}
parts.push('Now produce the blog-post outline.');
const userPrompt = parts.join('\n\n');

return [{
  json: {
    form,
    stats,
    outline_model: OUTLINE_MODEL,
    openrouter_api_key: OPENROUTER_API_KEY,
    openrouter_request: {
      model: OUTLINE_MODEL,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.3,
      max_tokens: 8192
    }
  }
}];

// Extract the markdown outline from the OpenRouter response.
const resp = $input.first().json;
const payload = $('Build Outline Prompt').first().json;

if (resp.error) {
  return [{ json: { error: 'OpenRouter returned error', detail: resp.error } }];
}

const outline = resp?.choices?.[0]?.message?.content;
if (!outline) {
  return [{ json: { error: 'No outline in OpenRouter response', raw: resp } }];
}

const cleaned = outline.replace(/^```(?:markdown|md)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

const result = {
  request: {
    topic: payload.form?.topic,
    focus_keyword: payload.form?.focus_keyword,
    header_keywords: payload.form?.header_keywords,
    entities: payload.form?.entities,
    common_keywords: payload.form?.common_keywords,
    extra_keywords: payload.form?.extra_keywords,
    target_word_count: payload.form?.target_word_count
  },
  outline: cleaned,
  model: payload.outline_model,
  usage: resp.usage || null,
  generated_at: new Date().toISOString()
};

if (payload.stats && payload.stats.stats_enabled) {
  result.stats = {
    enabled: true,
    source_count: payload.stats.source_count,
    stats_block: payload.stats.stats_block,
    error: payload.stats.error || null
  };
}

return [{ json: result }];

// Normalize inputs for the blog-post-content webhook.
const input = $input.first().json;
const form = (input && typeof input.body === 'object' && input.body !== null && Object.keys(input.body).length > 0)
  ? input.body
  : input;

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (...keys) => {
  for (const k of keys) {
    if (form[k] !== undefined && form[k] !== null && form[k] !== '') return form[k];
  }
  const targets = keys.map(norm);
  for (const k of Object.keys(form)) {
    const n = norm(k);
    if (targets.some(t => n === t || n.startsWith(t))) return form[k];
  }
  return '';
};

const toArr = v => {
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  if (typeof v === 'string') return v.split(/[,;\n]/).map(s => s.trim()).filter(Boolean);
  return [];
};

return [{
  json: {
    edited_outline: pick('edited_outline', 'outline', 'editedOutline') || '',
    focus_keyword: pick('focus_keyword', 'Focus Keyword', 'focusKeyword') || '',
    header_keywords: toArr(pick('header_keywords', 'Header Keywords', 'headerKeywords')),
    entities: toArr(pick('entities', 'Entities')),
    common_keywords: toArr(pick('common_keywords', 'Common Keywords', 'commonKeywords')),
    extra_keywords: toArr(pick('extra_keywords', 'Extra Keywords', 'extraKeywords')),
    target_word_count: parseInt(pick('target_word_count', 'Target Word Count', 'targetWordCount')) || 0,
    intent_context_text: String(pick('intent_context_text', 'intentContextText') || '').trim(),
    salience_context_text: String(pick('salience_context_text', 'salienceContextText') || '').trim(),
    audience_context_text: String(pick('audience_context_text', 'audienceContextText') || '').trim(),
    internal_links: Array.isArray(form.internal_links) ? form.internal_links.filter(u => typeof u === 'string' && /^https?:\/\//.test(u)) : []
  }
}];

// Build the OpenRouter request body for final blog content generation from the edited outline.
//
// REPLACE the OPENROUTER_API_KEY constant and tune CONTENT_MODEL below.

const OPENROUTER_API_KEY = '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';
const CONTENT_MODEL      = 'google/gemini-2.5-pro';

const form = $('Fetch Writing Style (Content)').first().json;

if (!form.edited_outline) {
  return [{ json: { error: 'edited_outline is required' } }];
}

// Word count enforcement calculation
const targetWC = form.target_word_count || 0;
let wcEnforcement = '';

if (targetWC > 0) {
  const h2Matches = (form.edited_outline || '').match(/^##\s+/gm) || [];
  const h2Count = Math.max(h2Matches.length, 1);
  const introWords = Math.round(targetWC * 0.10);
  const conclusionWords = Math.round(targetWC * 0.10);
  const bodyWords = targetWC - introWords - conclusionWords;
  const wordsPerH2 = Math.round(bodyWords / h2Count);

  wcEnforcement = '\n\nWORD COUNT ENFORCEMENT (NON-NEGOTIABLE):\n- TOTAL: ' + targetWC + ' words (\u00b15% tolerance: ' + Math.round(targetWC * 0.95) + '-' + Math.round(targetWC * 1.05) + ' words)\n- Intro paragraph: ' + introWords + ' words exactly\n- Each H2 section: ' + wordsPerH2 + ' words exactly (' + h2Count + ' sections)\n- Conclusion: ' + conclusionWords + ' words exactly\n\nRULES:\n1. Count words as you write each section\n2. Hit the target for EACH section, not just the total\n3. If a section is short, expand with examples, data, or explanations\n4. If a section is long, tighten prose without losing meaning\n5. Do NOT add filler to hit counts - every word must add value\n6. The final output MUST be within \u00b15% of ' + targetWC + ' words';
}

const systemPrompt = (form.writing_style_instructions ? '\n\nCRITICAL WRITING STYLE RULES (MANDATORY \u2014 follow EVERY rule below exactly. These OVERRIDE all other tone/style guidance):\n' + form.writing_style_instructions + '\n\n---\n\nThe CRITICAL rules above are your HIGHEST priority. Every sentence you write MUST comply with them. Now follow the additional SEO/structure rules below:\n\n' : '') +
'You are a senior blog editor and SEO copywriter. You write blog-post content that ranks in Google AND is quoted by LLM-based search.\n\n' +
'GROUNDING RULES (ordered by priority):\n' +
'1. SEARCH INTENT INSIGHTS (HIGHEST PRIORITY): If <intent_context> contains content, calibrate tone, depth, and CTAs to the stated primary intent. Transactional -> buy/subscribe CTAs. Informational -> no heavy sell, focus on teaching. If a recommended page archetype is specified (listicle, guide, how-to, comparison), you MUST follow that archetype. If a modifier-SERP conflict is flagged, follow that guidance.\n' +
'2. SALIENCE INSIGHTS (SECOND HIGHEST PRIORITY): If <salience_context> contains content, weave must-cover entities naturally throughout the body copy using exact entity names.\n' +
'3. Expand every section of the provided outline into final blog copy. Do NOT add, remove, or reorder sections unless the outline explicitly signals flexibility.\n' +
'4. Under every heading, write engaging, authentic prose. H2s get 2-4 paragraphs. H3s get 1-2 paragraphs. The intro hook should grab attention in the first sentence -- use a stat, a provocative statement, or a vivid anecdote as appropriate.\n' +
'5. Naturally weave in the Focus Keyword, Header Keywords, Entities, and Common Keywords. Use the Focus Keyword in the H1 and once in the opening paragraph. Use Entities where they add trust signals. Do not keyword-stuff.\n' +
'6. If the outline contains [Include anecdote: ...] tags, expand the anecdote into full narrative prose in that section. Make it personal and vivid.\n' +
'7. If the outline contains [POV: ...] tags, expand the opinion into a clear, confident position statement with supporting reasoning.\n' +
'8. If the outline contains [Include stat: ...] tags, present the statistic naturally with proper attribution -- "According to [source], ..." or similar phrasing. Do not fabricate stats not present in the outline tags.\n' +
'9. If <voice_context> was provided, the entire post must read in that voice -- every sentence, every transition, every takeaway. The voice is non-negotiable.\n' +
'10. For any [TO FILL] markers in the outline, leave a [TO FILL: <label>] placeholder instead of fabricating.\n' +
'11. AUDIENCE RESEARCH: If <audience_context> contains content, address the top user problems explicitly. Use the phrasing patterns from representative questions to write relatable copy.\n' +
'12. PARAGRAPH LENGTH (NON-NEGOTIABLE): Every paragraph must be a MINIMUM of 3 lines and a MAXIMUM of 4 lines. This is critical for readability -- large chunks of text ruin the reading experience. If a paragraph runs longer than 4 lines, break it into two paragraphs. If a paragraph is shorter than 3 lines, expand it with supporting detail or merge it with an adjacent paragraph.' +
'14. INTERNAL LINKING: If <internal_links> is provided, identify 3-5 places where internal links are contextually relevant. Insert them as markdown links: [descriptive anchor text](URL). Anchor text must be natural and match the linked page topic. Only use a link when the surrounding content genuinely relates to that URL. Never force irrelevant links.' +
wcEnforcement + '\n\n' +
'FORMAT: Pure markdown. Preserve H1/H2/H3 structure exactly. No preamble, no trailing commentary, no code fences.\n\n' +
'TONE: Match the provided voice exactly. If no voice provided, default to conversational, authoritative, and benefit-driven. Short sentences. No filler phrases. No fluff.' +
(form.writing_style_instructions ? '\n\nWRITING STYLE INSTRUCTIONS (follow these precisely):\n' + form.writing_style_instructions : '');

const parts = [];
// PRIORITY ORDER: intent > salience > keywords > anecdotes/opinions > audience > outline
parts.push('<intent_context>\n' + (form.intent_context_text || '(not provided)') + '\n</intent_context>');
parts.push('<salience_context>\n' + (form.salience_context_text || '(not provided)') + '\n</salience_context>');
parts.push('<marketer_inputs>\nFocus Keyword: ' + (form.focus_keyword || '(not set)') + '\nHeader Keywords: ' + ((form.header_keywords || []).join(', ') || '(not set)') + '\nEntities: ' + ((form.entities || []).join(', ') || '(not set)') + '\nCommon Keywords: ' + ((form.common_keywords || []).join(', ') || '(not set)') + '\nExtra Keywords: ' + ((form.extra_keywords || []).join(', ') || '(not set)') + (targetWC > 0 ? '\nTarget Word Count: ' + targetWC + ' words' : '') + '\n</marketer_inputs>');
// Anecdotes & Opinions reinforcement -- remind the AI of raw material even though outline tags carry them too
if (form.anecdotes || form.opinions) {
  let reinforce = '';
  if (form.anecdotes) reinforce += 'Anecdotes to incorporate:\n' + form.anecdotes;
  if (form.opinions) reinforce += (reinforce ? '\n\n' : '') + 'Opinions to weave in:\n' + form.opinions;
  parts.push('<anecdotes_opinions>\n' + reinforce + '\n</anecdotes_opinions>');
}
parts.push('<audience_context>\n' + (form.audience_context_text || '(not provided)') + '\n</audience_context>');
parts.push('<edited_outline>\n' + form.edited_outline + '\n</edited_outline>');
if (form.internal_links && form.internal_links.length > 0) {
  parts.push('<internal_links>\nAvailable internal URLs for contextual linking. Only use when the surrounding content genuinely matches the URL topic. Use the URL path to judge relevance.\n' + form.internal_links.map(u => '- ' + u).join('\n') + '\n</internal_links>');
}
parts.push((targetWC > 0 ? 'CRITICAL: You MUST write exactly ' + targetWC + ' words (\u00b15% tolerance). Count words as you write. Each section MUST hit its word count target.\n\n' : '') + 'Now expand the outline into final blog-post content.');
const userPrompt = parts.join('\n\n');

return [{
  json: {
    form,
    content_model: CONTENT_MODEL,
    openrouter_api_key: OPENROUTER_API_KEY,
    openrouter_request: {
      model: CONTENT_MODEL,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.35,
      max_tokens: 16384
    }
  }
}];

// Extract the final markdown content from the OpenRouter response.
const resp = $input.first().json;
const payload = $('Build Content Prompt').first().json;

if (payload.error) {
  return [{ json: payload }];
}

if (resp.error) {
  return [{ json: { error: 'OpenRouter returned error', detail: resp.error } }];
}

const content = resp?.choices?.[0]?.message?.content;
if (!content) {
  return [{ json: { error: 'No content in OpenRouter response', raw: resp } }];
}

const cleaned = content.replace(/^```(?:markdown|md)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

